        for c in range(w - 1):
            if (grid[r][c] == grid[r][c+1] ==
                grid[r+1][c] == grid[r+1][c+1] == 0):
                marker = c
                break
        if marker is not None:
            break
    if marker is None:
        return out
    for row in out:
        for c in (marker, marker + 1):
            if row[c] != 2:
                row[c] = 0
    return out
